+{
+  "$schema": "https://json-schema.org/draft/2020-12/schema",
+  "$id": "https://github.com/globulario/sensei/schema/admissioncomposition-request-v1.json",
+  "title": "Sensei ARCHER Admission Composition Request V1",
+  "description": "O5A's closed request document binding an exact candidate-ready O1/O3/O4 chain to a manifest-derived admission scope without modifying the frozen O1 receipt or replacing the existing admission owner.",
+  "type": "object",
+  "additionalProperties": false,
+  "required": [
+    "schema_version",
+    "request_id",
+    "generated_by",
+    "synthesis_receipt_digest_sha256",
+    "runner_receipt_digest_sha256",
+    "evaluation_receipt_digest_sha256",
+    "candidate_artifact_digest_sha256",
+    "repository_domain",
+    "base_revision",
+    "derived_scope",
+    "unsupported_operations",
+    "admission_eligible",
+    "admission_request_digest_sha256",
+    "admission_request_identity_digest_sha256",
+    "request_digest_sha256"
+  ],
+  "properties": {
+    "schema_version": { "const": "sensei.admissioncomposition.request.v1" },
+    "request_id": { "type": "string", "minLength": 1 },
+    "generated_by": { "const": "sensei-admission-composition" },
+    "synthesis_receipt_digest_sha256": { "$ref": "#/$defs/sha256Hex" },
+    "runner_receipt_digest_sha256": { "$ref": "#/$defs/sha256Hex" },
+    "evaluation_receipt_digest_sha256": { "$ref": "#/$defs/sha256Hex" },
+    "candidate_artifact_digest_sha256": { "$ref": "#/$defs/sha256Hex" },
+    "repository_domain": { "type": "string", "minLength": 1 },
+    "base_revision": { "type": "string", "minLength": 1 },
+    "derived_scope": { "$ref": "#/$defs/changeScope" },
+    "unsupported_operations": {
+      "type": "array",
+      "items": { "$ref": "#/$defs/unsupportedOperation" }
+    },
+    "admission_eligible": { "type": "boolean" },
+    "admission_request_digest_sha256": { "$ref": "#/$defs/optionalSha256Hex" },
+    "admission_request_identity_digest_sha256": { "$ref": "#/$defs/optionalSha256Hex" },
+    "request_digest_sha256": { "$ref": "#/$defs/sha256Hex" }
+  },
+  "allOf": [
+    {
+      "if": { "properties": { "admission_eligible": { "const": true } }, "required": ["admission_eligible"] },
+      "then": {
+        "properties": {
+          "unsupported_operations": { "maxItems": 0 },
+          "derived_scope": {
+            "properties": {
+              "files": { "minItems": 1 }
+            },
+            "required": ["files"]
+          },
+          "admission_request_digest_sha256": { "$ref": "#/$defs/sha256Hex" },
+          "admission_request_identity_digest_sha256": { "$ref": "#/$defs/sha256Hex" }
+        }
+      },
+      "else": {
+        "properties": {
+          "admission_request_digest_sha256": { "type": "null" },
+          "admission_request_identity_digest_sha256": { "type": "null" }
+        }
+      }
+    }
+  ],
+  "$defs": {
+    "sha256Hex": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
+    "optionalSha256Hex": {
+      "oneOf": [
+        { "$ref": "#/$defs/sha256Hex" },
+        { "type": "null" }
+      ]
+    },
+    "fileOperation": {
+      "type": "object",
+      "additionalProperties": false,
+      "required": ["path", "operation"],
+      "properties": {
+        "path": { "type": "string", "minLength": 1 },
+        "operation": { "const": "modify" }
+      }
+    },
+    "changeScope": {
+      "type": "object",
+      "additionalProperties": false,
+      "properties": {
+        "files": { "type": "array", "items": { "$ref": "#/$defs/fileOperation" } },
+        "symbols": { "type": "array", "items": { "type": "string", "minLength": 1 } },
+        "components": { "type": "array", "items": { "type": "string", "minLength": 1 } },
+        "claim_ids": { "type": "array", "items": { "type": "string", "minLength": 1 } },
+        "proposition_keys": { "type": "array", "items": { "type": "string", "minLength": 1 } }
+      }
+    },
+    "unsupportedOperation": {
+      "type": "object",
+      "additionalProperties": false,
+      "required": ["path", "operation", "detail"],
+      "properties": {
+        "path": { "type": "string" },
+        "operation": { "type": "string", "minLength": 1 },
+        "detail": { "type": "string", "minLength": 1 }
+      }
+    }
+  }
+}
diff --git a/golang/architecture/admissioncomposition/admissioncomposition_test.go b/golang/architecture/admissioncomposition/admissioncomposition_test.go
new file mode 100644
index 00000000..2a69a52a
--- /dev/null
+++ b/golang/architecture/admissioncomposition/admissioncomposition_test.go
@@ -0,0 +1,141 @@
+// SPDX-License-Identifier: AGPL-3.0-only
+
+package admissioncomposition
+
+import (
+	"testing"
+
+	"github.com/globulario/sensei/golang/architecture/admission"
+	"github.com/globulario/sensei/golang/architecture/evaluatorcomposition"
+	"github.com/globulario/sensei/golang/architecture/runnercomposition"
+)
+
+func TestComposeRequestDerivesExactModifyScope(t *testing.T) {
+	in := validInput(t)
+	req, concrete, err := ComposeRequest(in)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !req.AdmissionEligible || concrete == nil {
+		t.Fatal("expected admission-eligible request")
+	}
+	if len(req.DerivedScope.Files) != 1 || req.DerivedScope.Files[0] != (admission.FileOperation{Path: "a.txt", Operation: admission.OperationModify}) {
+		t.Fatalf("unexpected derived scope: %#v", req.DerivedScope)
+	}
+	if len(req.UnsupportedOperations) != 0 {
+		t.Fatalf("unexpected unsupported operations: %#v", req.UnsupportedOperations)
+	}
+	if err := ValidateRequest(req); err != nil {
+		t.Fatal(err)
+	}
+}
+
+func TestComposeRequestRejectsCrossLayerLineageTampering(t *testing.T) {
+	in := validInput(t)
+	in.EvaluationReceipt.RunnerReceiptDigestSHA256 = hex64("wrong-runner")
+	digest, err := evaluatorcomposition.EvaluationReceiptDigest(in.EvaluationReceipt)
+	if err != nil {
+		t.Fatal(err)
+	}
+	in.EvaluationReceipt.ReceiptDigestSHA256 = digest
+	if _, _, err := ComposeRequest(in); err == nil {
+		t.Fatal("expected O3/O4 lineage mismatch")
+	}
+}
+
+func TestDeriveScopePreservesUnsupportedOperations(t *testing.T) {
+	base := []runnercomposition.CandidateManifestEntry{
+		manifestEntry("delete.txt", []byte("old"), runnercomposition.ModeRegular),
+		manifestEntry("mode.txt", []byte("same"), runnercomposition.ModeRegular),
+	}
+	final := []runnercomposition.CandidateManifestEntry{
+		manifestEntry("add.txt", []byte("new"), runnercomposition.ModeRegular),
+		manifestEntry("mode.txt", []byte("same"), runnercomposition.ModeExecutable),
+	}
+	scope, unsupported, err := deriveScope(base, final)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(scope.Files) != 0 {
+		t.Fatalf("unsupported operations leaked into modify scope: %#v", scope.Files)
+	}
+	if len(unsupported) != 3 {
+		t.Fatalf("expected add/delete/type-change, got %#v", unsupported)
+	}
+}
+
+func TestUnsupportedReceiptCarriesNoAdmissionEvidence(t *testing.T) {
+	req := NormalizeRequest(Request{
+		SchemaVersion:                 RequestSchemaVersion,
+		RequestID:                     "o5a.unsupported",
+		GeneratedBy:                   GeneratedBy,
+		SynthesisReceiptDigestSHA256:  hex64("o1"),
+		RunnerReceiptDigestSHA256:     hex64("o3"),
+		EvaluationReceiptDigestSHA256: hex64("o4"),
+		CandidateArtifactDigestSHA256: hex64("artifact"),
+		RepositoryDomain:              "github.com/globulario/sensei",
+		BaseRevision:                  "0123456789012345678901234567890123456789",
+		DerivedScope:                  admission.ChangeScope{},
+		UnsupportedOperations: []UnsupportedOperation{{
+			Path:      "new.txt",
+			Operation: admission.ChangeAdded,
+			Detail:    "existing admission supports read/modify only",
+		}},
+	})
+	digest, err := RequestDigest(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	req.RequestDigestSHA256 = digest
+	receipt, err := ComposeUnsupportedReceipt(req, "2026-08-01T23:00:00Z")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if receipt.AdmissionDecision != nil || receipt.AdmissionDecisionDigestSHA256 != nil || receipt.AdmissionVerificationStatus != nil || receipt.AdmissionVerificationDigestSHA256 != nil {
+		t.Fatal("unsupported receipt manufactured admission evidence")
+	}
+}
+
+func TestDecisionAndVerificationRemainBesideFrozenO1Receipt(t *testing.T) {
+	in := validInput(t)
+	req, concrete, err := ComposeRequest(in)
+	if err != nil {
+		t.Fatal(err)
+	}
+	decision := canonicalDecision(t, *concrete, *req.AdmissionRequestIdentityDigestSHA256)
+	receipt, err := ComposeDecisionReceipt(req, *concrete, decision, "2026-08-01T23:00:00Z")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if in.SynthesisReceipt.AdmissionDecisionDigestSHA256 != nil || in.SynthesisReceipt.AdmissionVerificationDigestSHA256 != nil {
+		t.Fatal("O5A mutated the frozen O1 receipt")
+	}
+	verification := canonicalVerification(t, decision)
+	finalReceipt, err := AttachVerification(receipt, decision, verification, "2026-08-01T23:01:00Z")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if finalReceipt.Disposition != DispositionVerificationRecorded || finalReceipt.AdmissionVerificationDigestSHA256 == nil {
+		t.Fatalf("verification not recorded: %#v", finalReceipt)
+	}
+}
+
+func TestReceiptIdentityExcludesObservationTime(t *testing.T) {
+	in := validInput(t)
+	req, concrete, err := ComposeRequest(in)
+	if err != nil {
+		t.Fatal(err)
+	}
+	decision := canonicalDecision(t, *concrete, *req.AdmissionRequestIdentityDigestSHA256)
+	a, err := ComposeDecisionReceipt(req, *concrete, decision, "2026-08-01T23:00:00Z")
+	if err != nil {
+		t.Fatal(err)
+	}
+	b, err := ComposeDecisionReceipt(req, *concrete, decision, "2026-08-02T01:00:00Z")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if a.ReceiptDigestSHA256 != b.ReceiptDigestSHA256 {
+		t.Fatal("observation time changed semantic receipt identity")
+	}
+}
diff --git a/golang/architecture/admissioncomposition/compose.go b/golang/architecture/admissioncomposition/compose.go
new file mode 100644
index 00000000..6db807e3
--- /dev/null
+++ b/golang/architecture/admissioncomposition/compose.go
@@ -0,0 +1,174 @@
+// SPDX-License-Identifier: AGPL-3.0-only
+
+package admissioncomposition
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+
+	"github.com/globulario/sensei/golang/architecture/admission"
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+)
+
+func ComposeRequest(in ComposeInput) (Request, *admission.Request, error) {
+	if err := validateChain(in); err != nil {
+		return Request{}, nil, err
+	}
+	scope, unsupported, err := deriveScope(in.BaseManifest, in.CandidateArtifact.Manifest)
+	if err != nil {
+		return Request{}, nil, err
+	}
+	r := NormalizeRequest(Request{
+		SchemaVersion:                 RequestSchemaVersion,
+		RequestID:                     "o5a." + in.CandidateArtifact.CandidateArtifactDigestSHA256[:12] + "." + in.SynthesisReceipt.ReceiptDigestSHA256[:12],
+		GeneratedBy:                   GeneratedBy,
+		SynthesisReceiptDigestSHA256:  in.SynthesisReceipt.ReceiptDigestSHA256,
+		RunnerReceiptDigestSHA256:     in.RunnerReceipt.RunnerReceiptDigestSHA256,
+		EvaluationReceiptDigestSHA256: in.EvaluationReceipt.ReceiptDigestSHA256,
+		CandidateArtifactDigestSHA256: in.CandidateArtifact.CandidateArtifactDigestSHA256,
+		RepositoryDomain:              in.CandidateArtifact.RepositoryDomain,
+		BaseRevision:                  in.CandidateArtifact.BaseRevision,
+		DerivedScope:                  scope,
+		UnsupportedOperations:         unsupported,
+	})
+
+	var concrete *admission.Request
+	if len(unsupported) == 0 && len(scope.Files) > 0 {
+		candidate := in.AdmissionTemplate
+		candidate.SchemaVersion = admission.SchemaVersion
+		candidate.Mode = admission.ModeModify
+		candidate.Scope = scope
+		normalized, err := admission.NormalizeRequest(candidate)
+		if err != nil {
+			return Request{}, nil, fmt.Errorf("admissioncomposition: normalize admission request: %w", err)
+		}
+		if normalized.Binding.RepositoryDomain != r.RepositoryDomain || normalized.Binding.Revision != r.BaseRevision {
+			return Request{}, nil, errors.New("admissioncomposition: admission binding does not match candidate repository/base")
+		}
+		documentDigest, err := closureprotocol.SemanticDigest(normalized)
+		if err != nil {
+			return Request{}, nil, err
+		}
+		identityDigest, err := admissionRequestIdentityDigest(normalized)
+		if err != nil {
+			return Request{}, nil, err
+		}
+		r.DerivedScope = normalized.Scope
+		r.AdmissionEligible = true
+		r.AdmissionRequestDigestSHA256 = &documentDigest
+		r.AdmissionRequestIdentityDigestSHA256 = &identityDigest
+		concrete = &normalized
+	}
+
+	digest, err := RequestDigest(r)
+	if err != nil {
+		return Request{}, nil, err
+	}
+	r.RequestDigestSHA256 = digest
+	if err := ValidateRequest(r); err != nil {
+		return Request{}, nil, err
+	}
+	return r, concrete, nil
+}
+
+func ComposeUnsupportedReceipt(req Request, completedAt string) (Receipt, error) {
+	if err := ValidateRequest(req); err != nil {
+		return Receipt{}, err
+	}
+	if req.AdmissionEligible {
+		return Receipt{}, errors.New("admissioncomposition: eligible request cannot produce unsupported-operation receipt")
+	}
+	r := Receipt{
+		SchemaVersion:                 ReceiptSchemaVersion,
+		ReceiptID:                     "o5a-receipt." + req.RequestDigestSHA256[:16],
+		GeneratedBy:                   GeneratedBy,
+		RequestDigestSHA256:           req.RequestDigestSHA256,
+		SynthesisReceiptDigestSHA256:  req.SynthesisReceiptDigestSHA256,
+		CandidateArtifactDigestSHA256: req.CandidateArtifactDigestSHA256,
+		Disposition:                   DispositionUnsupportedOperationRefused,
+		Detail:                        unsupportedDetail(req.UnsupportedOperations),
+		CompletedAt:                   completedAt,
+	}
+	return finalizeReceipt(r)
+}
+
+func ComposeDecisionReceipt(req Request, concrete admission.Request, decision admission.Decision, completedAt string) (Receipt, error) {
+	if err := ValidateRequest(req); err != nil {
+		return Receipt{}, err
+	}
+	if !req.AdmissionEligible || req.AdmissionRequestIdentityDigestSHA256 == nil {
+		return Receipt{}, errors.New("admissioncomposition: request is not eligible for admission")
+	}
+	normalized, err := admission.NormalizeRequest(concrete)
+	if err != nil {
+		return Receipt{}, err
+	}
+	identity, err := admissionRequestIdentityDigest(normalized)
+	if err != nil {
+		return Receipt{}, err
+	}
+	if identity != *req.AdmissionRequestIdentityDigestSHA256 || !reflect.DeepEqual(normalized.Scope, req.DerivedScope) {
+		return Receipt{}, errors.New("admissioncomposition: admission request does not match composed request")
+	}
+	canonicalDecision, err := validateDecision(decision)
+	if err != nil {
+		return Receipt{}, err
+	}
+	if canonicalDecision.RequestReceipt.DigestSHA256 != identity || !reflect.DeepEqual(canonicalDecision.RequestReceipt.Scope, normalized.Scope) || canonicalDecision.RequestedMode != admission.ModeModify {
+		return Receipt{}, errors.New("admissioncomposition: decision is not bound to the composed admission request")
+	}
+	decisionValue := canonicalDecision.Decision
+	decisionDigest := canonicalDecision.DecisionDigestSHA256
+	return finalizeReceipt(Receipt{
+		SchemaVersion:                 ReceiptSchemaVersion,
+		ReceiptID:                     "o5a-receipt." + req.RequestDigestSHA256[:16],
+		GeneratedBy:                   GeneratedBy,
+		RequestDigestSHA256:           req.RequestDigestSHA256,
+		SynthesisReceiptDigestSHA256:  req.SynthesisReceiptDigestSHA256,
+		CandidateArtifactDigestSHA256: req.CandidateArtifactDigestSHA256,
+		AdmissionDecision:             &decisionValue,
+		AdmissionDecisionDigestSHA256: &decisionDigest,
+		Disposition:                   DispositionAdmissionDecided,
+		CompletedAt:                   completedAt,
+	})
+}
+
+func AttachVerification(receipt Receipt, decision admission.Decision, verification admission.Verification, completedAt string) (Receipt, error) {
+	if err := ValidateReceipt(receipt); err != nil {
+		return Receipt{}, err
+	}
+	if receipt.Disposition != DispositionAdmissionDecided || receipt.AdmissionDecisionDigestSHA256 == nil {
+		return Receipt{}, errors.New("admissioncomposition: verification requires an admission-decided receipt")
+	}
+	canonicalDecision, err := validateDecision(decision)
+	if err != nil {
+		return Receipt{}, err
+	}
+	if canonicalDecision.DecisionDigestSHA256 != *receipt.AdmissionDecisionDigestSHA256 {
+		return Receipt{}, errors.New("admissioncomposition: decision digest changed before verification")
+	}
+	canonicalVerification, err := validateVerification(verification)
+	if err != nil {
+		return Receipt{}, err
+	}
+	if canonicalVerification.AdmissionID != canonicalDecision.AdmissionID || canonicalVerification.DecisionDigestSHA256 != canonicalDecision.DecisionDigestSHA256 || !reflect.DeepEqual(canonicalVerification.Binding, canonicalDecision.Binding) {
+		return Receipt{}, errors.New("admissioncomposition: verification is not bound to the admitted decision")
+	}
+	status := canonicalVerification.Status
+	verificationDigest := canonicalVerification.VerificationDigestSHA256
+	receipt.AdmissionVerificationStatus = &status
+	receipt.AdmissionVerificationDigestSHA256 = &verificationDigest
+	receipt.Disposition = DispositionVerificationRecorded
+	receipt.CompletedAt = completedAt
+	return finalizeReceipt(receipt)
+}
+
+func finalizeReceipt(r Receipt) (Receipt, error) {
+	digest, err := ReceiptDigest(r)
+	if err != nil {
+		return Receipt{}, err
+	}
+	r.ReceiptDigestSHA256 = digest
+	return r, ValidateReceipt(r)
+}
diff --git a/golang/architecture/admissioncomposition/digest.go b/golang/architecture/admissioncomposition/digest.go
new file mode 100644
index 00000000..823efe16
--- /dev/null
+++ b/golang/architecture/admissioncomposition/digest.go
@@ -0,0 +1,52 @@
+// SPDX-License-Identifier: AGPL-3.0-only
+
+package admissioncomposition
+
+import (
+	"crypto/sha256"
+	"encoding/hex"
+
+	"github.com/globulario/sensei/golang/architecture/admission"
+	"github.com/globulario/sensei/golang/architecture/closureprotocol"
+)
+
+func NormalizeRequest(in Request) Request {
+	r := in
+	if r.DerivedScope.Files == nil {
+		r.DerivedScope.Files = []admission.FileOperation{}
+	}
+	if r.DerivedScope.Symbols == nil {
+		r.DerivedScope.Symbols = []string{}
+	}
+	if r.DerivedScope.Components == nil {
+		r.DerivedScope.Components = []string{}
+	}
+	if r.DerivedScope.ClaimIDs == nil {
+		r.DerivedScope.ClaimIDs = []string{}
+	}
+	if r.DerivedScope.PropositionKeys == nil {
+		r.DerivedScope.PropositionKeys = []string{}
+	}
+	if r.UnsupportedOperations == nil {
+		r.UnsupportedOperations = []UnsupportedOperation{}
+	}
+	return r
+}
+
+func RequestDigest(in Request) (string, error) {
+	r := NormalizeRequest(in)
+	r.RequestDigestSHA256 = ""
+	return closureprotocol.SemanticDigest(r)
+}
+
+func ReceiptDigest(in Receipt) (string, error) {
+	r := in
+	r.ReceiptDigestSHA256 = ""
+	r.CompletedAt = ""
+	return closureprotocol.SemanticDigest(r)
+}
+
+func sha256Hex(data []byte) string {
+	sum := sha256.Sum256(data)
+	return hex.EncodeToString(sum[:])
+}
