diff --git a/golang/architecture/admissioncomposition/scope.go b/golang/architecture/admissioncomposition/scope.go
new file mode 100644
index 00000000..3fe5cf4b
--- /dev/null
+++ b/golang/architecture/admissioncomposition/scope.go
@@ -0,0 +1,129 @@
+// SPDX-License-Identifier: AGPL-3.0-only
+
+package admissioncomposition
+
+import (
+	"bytes"
+	"encoding/json"
+	"errors"
+	"sort"
+	"strings"
+
+	"github.com/globulario/sensei/golang/architecture/admission"
+	"github.com/globulario/sensei/golang/architecture/runnercomposition"
+)
+
+func deriveScope(base, final []runnercomposition.CandidateManifestEntry) (admission.ChangeScope, []UnsupportedOperation, error) {
+	baseCanonical, err := runnercomposition.CanonicalizeManifest(base)
+	if err != nil {
+		return admission.ChangeScope{}, nil, err
+	}
+	finalCanonical, err := runnercomposition.CanonicalizeManifest(final)
+	if err != nil {
+		return admission.ChangeScope{}, nil, err
+	}
+	baseByPath := make(map[string]runnercomposition.CandidateManifestEntry, len(baseCanonical))
+	finalByPath := make(map[string]runnercomposition.CandidateManifestEntry, len(finalCanonical))
+	paths := map[string]bool{}
+	for _, entry := range baseCanonical {
+		baseByPath[entry.Path] = entry
+		paths[entry.Path] = true
+	}
+	for _, entry := range finalCanonical {
+		finalByPath[entry.Path] = entry
+		paths[entry.Path] = true
+	}
+	ordered := make([]string, 0, len(paths))
+	for path := range paths {
+		ordered = append(ordered, path)
+	}
+	sort.Strings(ordered)
+	scope := admission.ChangeScope{
+		Files:           []admission.FileOperation{},
+		Symbols:         []string{},
+		Components:      []string{},
+		ClaimIDs:        []string{},
+		PropositionKeys: []string{},
+	}
+	unsupported := []UnsupportedOperation{}
+	for _, path := range ordered {
+		before, hadBefore := baseByPath[path]
+		after, hasAfter := finalByPath[path]
+		switch {
+		case hadBefore && !hasAfter:
+			unsupported = append(unsupported, UnsupportedOperation{Path: path, Operation: admission.ChangeDeleted, Detail: "existing admission supports read/modify only"})
+		case !hadBefore && hasAfter:
+			unsupported = append(unsupported, UnsupportedOperation{Path: path, Operation: admission.ChangeAdded, Detail: "existing admission supports read/modify only"})
+		case before.Mode != after.Mode:
+			unsupported = append(unsupported, UnsupportedOperation{Path: path, Operation: admission.ChangeTypeChanged, Detail: "candidate changed the governed file mode/type"})
+		case before.Mode == runnercomposition.ModeSymlink && (before.ContentDigestSHA256 != after.ContentDigestSHA256 || before.SymlinkTarget != after.SymlinkTarget):
+			unsupported = append(unsupported, UnsupportedOperation{Path: path, Operation: "symlink_changed", Detail: "symlink mutation is outside the current admission operation vocabulary"})
+		case before.ContentDigestSHA256 != after.ContentDigestSHA256 || !bytes.Equal(before.Content, after.Content):
+			scope.Files = append(scope.Files, admission.FileOperation{Path: path, Operation: admission.OperationModify})
+		}
+	}
+	return scope, unsupported, nil
+}
+
+func admissionRequestIdentityDigest(req admission.Request) (string, error) {
+	req.RequestedBy = ""
+	req.Note = ""
+	data, err := admission.MarshalCanonicalRequestYAML(req)
+	if err != nil {
+		return "", err
+	}
+	return sha256Hex(data), nil
+}
+
+func validateDecision(in admission.Decision) (admission.Decision, error) {
+	data, err := admission.MarshalCanonicalDecisionJSON(in)
+	if err != nil {
+		return admission.Decision{}, err
+	}
+	var env struct {
+		ArchitectureAdmissionDecision admission.Decision `json:"architecture_admission_decision"`
+	}
+	if err := json.Unmarshal(data, &env); err != nil {
+		return admission.Decision{}, err
+	}
+	out := env.ArchitectureAdmissionDecision
+	if out.DecisionDigestSHA256 != in.DecisionDigestSHA256 {
+		return admission.Decision{}, errors.New("admissioncomposition: admission decision digest invalid")
+	}
+	if out.CorrectnessCertified || !out.ScopeOnly {
+		return admission.Decision{}, errors.New("admissioncomposition: admission decision exceeds scope-only authority")
+	}
+	return out, nil
+}
+
+func validateVerification(in admission.Verification) (admission.Verification, error) {
+	data, err := admission.MarshalCanonicalVerificationJSON(in)
+	if err != nil {
+		return admission.Verification{}, err
+	}
+	var env struct {
+		ArchitectureAdmissionVerification admission.Verification `json:"architecture_admission_verification"`
+	}
+	if err := json.Unmarshal(data, &env); err != nil {
+		return admission.Verification{}, err
+	}
+	out := env.ArchitectureAdmissionVerification
+	if out.VerificationDigestSHA256 != in.VerificationDigestSHA256 {
+		return admission.Verification{}, errors.New("admissioncomposition: admission verification digest invalid")
+	}
+	if out.CorrectnessCertified || !out.ScopeOnly {
+		return admission.Verification{}, errors.New("admissioncomposition: admission verification exceeds scope-only authority")
+	}
+	return out, nil
+}
+
+func unsupportedDetail(ops []UnsupportedOperation) string {
+	if len(ops) == 0 {
+		return "candidate produced no supported modify operation"
+	}
+	parts := make([]string, 0, len(ops))
+	for _, op := range ops {
+		parts = append(parts, op.Operation+":"+op.Path)
+	}
+	return "unsupported candidate operations: " + strings.Join(parts, ",")
+}
diff --git a/golang/architecture/admissioncomposition/types.go b/golang/architecture/admissioncomposition/types.go
new file mode 100644
index 00000000..7e17b28c
--- /dev/null
+++ b/golang/architecture/admissioncomposition/types.go
@@ -0,0 +1,89 @@
+// SPDX-License-Identifier: AGPL-3.0-only
+
+// Package admissioncomposition composes the accepted O1, O3, O4 and
+// admission owners without replacing any of them. It validates the exact
+// candidate-ready lineage, derives the requested mutation scope from sealed
+// manifests, and records admission/verification evidence beside the frozen
+// O1 receipt. Its request and receipt surfaces are closed Draft 2020-12
+// documents validated from byte-identical embedded and canonical schemas.
+package admissioncomposition
+
+import (
+	"github.com/globulario/sensei/golang/architecture/admission"
+	"github.com/globulario/sensei/golang/architecture/evaluatorcomposition"
+	"github.com/globulario/sensei/golang/architecture/runnercomposition"
+	"github.com/globulario/sensei/golang/architecture/synthesis"
+)
+
+const (
+	RequestSchemaVersion = "sensei.admissioncomposition.request.v1"
+	ReceiptSchemaVersion = "sensei.admissioncomposition.receipt.v1"
+	GeneratedBy          = "sensei-admission-composition"
+)
+
+type Disposition string
+
+const (
+	DispositionUnsupportedOperationRefused Disposition = "unsupported-operation-refused"
+	DispositionAdmissionDecided            Disposition = "admission-decided"
+	DispositionVerificationRecorded        Disposition = "verification-recorded"
+)
+
+type UnsupportedOperation struct {
+	Path      string `json:"path"`
+	Operation string `json:"operation"`
+	Detail    string `json:"detail"`
+}
+
+type Request struct {
+	SchemaVersion string `json:"schema_version"`
+	RequestID     string `json:"request_id"`
+	GeneratedBy   string `json:"generated_by"`
+
+	SynthesisReceiptDigestSHA256  string `json:"synthesis_receipt_digest_sha256"`
+	RunnerReceiptDigestSHA256     string `json:"runner_receipt_digest_sha256"`
+	EvaluationReceiptDigestSHA256 string `json:"evaluation_receipt_digest_sha256"`
+	CandidateArtifactDigestSHA256 string `json:"candidate_artifact_digest_sha256"`
+
+	RepositoryDomain string `json:"repository_domain"`
+	BaseRevision     string `json:"base_revision"`
+
+	DerivedScope          admission.ChangeScope  `json:"derived_scope"`
+	UnsupportedOperations []UnsupportedOperation `json:"unsupported_operations"`
+	AdmissionEligible     bool                   `json:"admission_eligible"`
+
+	AdmissionRequestDigestSHA256         *string `json:"admission_request_digest_sha256"`
+	AdmissionRequestIdentityDigestSHA256 *string `json:"admission_request_identity_digest_sha256"`
+
+	RequestDigestSHA256 string `json:"request_digest_sha256"`
+}
+
+type Receipt struct {
+	SchemaVersion string `json:"schema_version"`
+	ReceiptID     string `json:"receipt_id"`
+	GeneratedBy   string `json:"generated_by"`
+
+	RequestDigestSHA256           string `json:"request_digest_sha256"`
+	SynthesisReceiptDigestSHA256  string `json:"synthesis_receipt_digest_sha256"`
+	CandidateArtifactDigestSHA256 string `json:"candidate_artifact_digest_sha256"`
+
+	AdmissionDecision                 *string `json:"admission_decision"`
+	AdmissionDecisionDigestSHA256     *string `json:"admission_decision_digest_sha256"`
+	AdmissionVerificationStatus       *string `json:"admission_verification_status"`
+	AdmissionVerificationDigestSHA256 *string `json:"admission_verification_digest_sha256"`
+
+	Disposition Disposition `json:"disposition"`
+	Detail      string      `json:"detail"`
+	CompletedAt string      `json:"completed_at"`
+
+	ReceiptDigestSHA256 string `json:"receipt_digest_sha256"`
+}
+
+type ComposeInput struct {
+	SynthesisReceipt  synthesis.Receipt
+	RunnerReceipt     runnercomposition.RunnerReceipt
+	EvaluationReceipt evaluatorcomposition.EvaluationReceipt
+	CandidateArtifact runnercomposition.CandidateArtifact
+	BaseManifest      []runnercomposition.CandidateManifestEntry
+	AdmissionTemplate admission.Request
+}
diff --git a/golang/architecture/admissioncomposition/validate.go b/golang/architecture/admissioncomposition/validate.go
new file mode 100644
index 00000000..e81c8540
--- /dev/null
+++ b/golang/architecture/admissioncomposition/validate.go
@@ -0,0 +1,145 @@
+// SPDX-License-Identifier: AGPL-3.0-only
+
+package admissioncomposition
+
+import (
+	"encoding/hex"
+	"errors"
+	"fmt"
+	"strings"
+
+	"github.com/globulario/sensei/golang/architecture/admission"
+)
+
+func ValidateRequest(in Request) error {
+	r := NormalizeRequest(in)
+	if r.SchemaVersion != RequestSchemaVersion || r.GeneratedBy != GeneratedBy {
+		return errors.New("admissioncomposition: unsupported request identity")
+	}
+	if strings.TrimSpace(r.RequestID) == "" || strings.TrimSpace(r.RepositoryDomain) == "" || strings.TrimSpace(r.BaseRevision) == "" {
+		return errors.New("admissioncomposition: request identity fields are required")
+	}
+	for _, digest := range []string{
+		r.SynthesisReceiptDigestSHA256,
+		r.RunnerReceiptDigestSHA256,
+		r.EvaluationReceiptDigestSHA256,
+		r.CandidateArtifactDigestSHA256,
+		r.RequestDigestSHA256,
+	} {
+		if !isSHA256(digest) {
+			return errors.New("admissioncomposition: request contains a non-SHA-256 digest")
+		}
+	}
+	seen := map[string]bool{}
+	for _, op := range r.DerivedScope.Files {
+		if strings.TrimSpace(op.Path) == "" || op.Operation != admission.OperationModify {
+			return errors.New("admissioncomposition: derived scope may contain only exact modify operations")
+		}
+		if seen[op.Path] {
+			return fmt.Errorf("admissioncomposition: duplicate derived path %q", op.Path)
+		}
+		seen[op.Path] = true
+	}
+	for _, op := range r.UnsupportedOperations {
+		if strings.TrimSpace(op.Operation) == "" || strings.TrimSpace(op.Detail) == "" {
+			return errors.New("admissioncomposition: unsupported operation requires operation and detail")
+		}
+	}
+	if r.AdmissionEligible {
+		if len(r.UnsupportedOperations) != 0 || len(r.DerivedScope.Files) == 0 || r.AdmissionRequestDigestSHA256 == nil || r.AdmissionRequestIdentityDigestSHA256 == nil {
+			return errors.New("admissioncomposition: eligible request has incomplete admission evidence")
+		}
+		if !isSHA256(*r.AdmissionRequestDigestSHA256) || !isSHA256(*r.AdmissionRequestIdentityDigestSHA256) {
+			return errors.New("admissioncomposition: admission request digests are invalid")
+		}
+	} else if r.AdmissionRequestDigestSHA256 != nil || r.AdmissionRequestIdentityDigestSHA256 != nil {
+		return errors.New("admissioncomposition: ineligible request must not carry admission request digests")
+	}
+	want, err := RequestDigest(r)
+	if err != nil {
+		return err
+	}
+	if r.RequestDigestSHA256 != want {
+		return fmt.Errorf("admissioncomposition: request digest mismatch: got %s want %s", r.RequestDigestSHA256, want)
+	}
+	return nil
+}
+
+func ValidateReceipt(r Receipt) error {
+	if r.SchemaVersion != ReceiptSchemaVersion || r.GeneratedBy != GeneratedBy || strings.TrimSpace(r.ReceiptID) == "" {
+		return errors.New("admissioncomposition: unsupported receipt identity")
+	}
+	for _, digest := range []string{
+		r.RequestDigestSHA256,
+		r.SynthesisReceiptDigestSHA256,
+		r.CandidateArtifactDigestSHA256,
+		r.ReceiptDigestSHA256,
+	} {
+		if !isSHA256(digest) {
+			return errors.New("admissioncomposition: receipt contains a non-SHA-256 digest")
+		}
+	}
+	switch r.Disposition {
+	case DispositionUnsupportedOperationRefused:
+		if r.AdmissionDecision != nil || r.AdmissionDecisionDigestSHA256 != nil || r.AdmissionVerificationStatus != nil || r.AdmissionVerificationDigestSHA256 != nil || strings.TrimSpace(r.Detail) == "" {
+			return errors.New("admissioncomposition: unsupported-operation receipt has invalid evidence presence")
+		}
+	case DispositionAdmissionDecided:
+		if r.AdmissionDecision == nil || r.AdmissionDecisionDigestSHA256 == nil || r.AdmissionVerificationStatus != nil || r.AdmissionVerificationDigestSHA256 != nil {
+			return errors.New("admissioncomposition: admission-decided receipt has invalid evidence presence")
+		}
+	case DispositionVerificationRecorded:
+		if r.AdmissionDecision == nil || r.AdmissionDecisionDigestSHA256 == nil || r.AdmissionVerificationStatus == nil || r.AdmissionVerificationDigestSHA256 == nil {
+			return errors.New("admissioncomposition: verification-recorded receipt has invalid evidence presence")
+		}
+	default:
+		return errors.New("admissioncomposition: unknown receipt disposition")
+	}
+	for _, p := range []*string{r.AdmissionDecisionDigestSHA256, r.AdmissionVerificationDigestSHA256} {
+		if p != nil && !isSHA256(*p) {
+			return errors.New("admissioncomposition: referenced admission digest is invalid")
+		}
+	}
+	if r.AdmissionDecision != nil && !oneOf(*r.AdmissionDecision,
+		admission.DecisionAdmitted,
+		admission.DecisionAdmittedWithConditions,
+		admission.DecisionWaiting,
+		admission.DecisionRefused,
+		admission.DecisionUncertifiable,
+	) {
+		return errors.New("admissioncomposition: unknown admission decision")
+	}
+	if r.AdmissionVerificationStatus != nil && !oneOf(*r.AdmissionVerificationStatus,
+		admission.VerificationScopeCompliant,
+		admission.VerificationScopeViolated,
+		admission.VerificationStale,
+		admission.VerificationUncertifiable,
+	) {
+		return errors.New("admissioncomposition: unknown verification status")
+	}
+	want, err := ReceiptDigest(r)
+	if err != nil {
+		return err
+	}
+	if r.ReceiptDigestSHA256 != want {
+		return fmt.Errorf("admissioncomposition: receipt digest mismatch: got %s want %s", r.ReceiptDigestSHA256, want)
+	}
+	return nil
+}
+
+func isSHA256(value string) bool {
+	if len(value) != 64 || value != strings.ToLower(value) {
+		return false
+	}
+	_, err := hex.DecodeString(value)
+	return err == nil
+}
+
+func oneOf(value string, allowed ...string) bool {
+	for _, candidate := range allowed {
+		if value == candidate {
+			return true
+		}
+	}
+	return false
+}
